import { EMPTY, cloneBoard, type Board } from './grid';
import { findGroups } from './groups';
import { settle, type RuleName } from './rules';

/**
 * Solvers and simulated players. Pure, deterministic, no DOM and no clock: the same board always gives the same
 * answer on every machine, so the board library can be regenerated byte for byte.
 *
 * A solution is a list of taps (cell indices). Each tap is the top-left-most cell of the group it lifts, so a
 * mirrored board is solved by the mirrored taps, and a recolored board by the same taps.
 */

/** Lift a group (already found) and settle. Returns a new board. */
function liftGroup(b: Board, group: readonly number[], rule: RuleName): Board {
  const next = cloneBoard(b);
  for (const j of group) next.cells[j] = EMPTY;
  settle(next, rule);
  return next;
}

function isEmptyCells(cells: Int8Array): boolean {
  for (let i = 0; i < cells.length; i++) if (cells[i] !== EMPTY) return false;
  return true;
}

const keyBuf: number[] = [];
/** Board contents as a string key (one char per cell), for merging identical boards. */
function cellsKey(cells: Int8Array): string {
  keyBuf.length = cells.length;
  for (let i = 0; i < cells.length; i++) keyBuf[i] = cells[i] + 66;
  return String.fromCharCode.apply(null, keyBuf);
}

/** Scratch space for countGroups, grown as needed and reused (the solver runs on one thread at a time). */
let stamp = new Int32Array(0);
let stack = new Int32Array(0);
let stampGen = 0;

/** Number of groups on a board: the same as findGroups(b).groups.length, without building the lists. */
export function countGroups(b: Board): number {
  const { cols, cells } = b;
  const n = cells.length;
  if (stamp.length < n) {
    stamp = new Int32Array(n);
    stack = new Int32Array(n);
    stampGen = 0;
  }
  if (++stampGen > 0x7ffffff0) {
    stamp.fill(0);
    stampGen = 1;
  }
  const gen = stampGen;
  let count = 0;
  for (let s = 0; s < n; s++) {
    const k = cells[s];
    if (k === EMPTY || stamp[s] === gen) continue;
    count++;
    stamp[s] = gen;
    let top = 0;
    stack[top++] = s;
    while (top) {
      const i = stack[--top];
      const c = i % cols;
      if (i >= cols && stamp[i - cols] !== gen && cells[i - cols] === k) {
        stamp[i - cols] = gen;
        stack[top++] = i - cols;
      }
      if (i + cols < n && stamp[i + cols] !== gen && cells[i + cols] === k) {
        stamp[i + cols] = gen;
        stack[top++] = i + cols;
      }
      if (c > 0 && stamp[i - 1] !== gen && cells[i - 1] === k) {
        stamp[i - 1] = gen;
        stack[top++] = i - 1;
      }
      if (c < cols - 1 && stamp[i + 1] !== gen && cells[i + 1] === k) {
        stamp[i + 1] = gen;
        stack[top++] = i + 1;
      }
    }
  }
  return count;
}

function distinctColors(cells: Int8Array): number {
  let mask = 0;
  for (let i = 0; i < cells.length; i++) if (cells[i] !== EMPTY) mask |= 1 << cells[i];
  let n = 0;
  while (mask) {
    n += mask & 1;
    mask >>>= 1;
  }
  return n;
}

// ---------------------------------------------------------------- beam search

interface BeamNode {
  board: Board;
  parent: BeamNode | null;
  tap: number;
}

function pathOf(node: BeamNode | null, last?: number): number[] {
  const taps: number[] = [];
  if (last !== undefined) taps.push(last);
  for (let n = node; n && n.parent; n = n.parent) taps.push(n.tap);
  return taps.reverse();
}

/**
 * Beam search, as in the plan: explore one move at a time, keep the `width` boards with the fewest groups left,
 * merge identical boards reached by different orders. Ties keep discovery order, so the result is deterministic.
 * Returns the taps of the first solution found (the shortest within the beam). Never fails: single blocks can
 * always be lifted, so every board can be emptied.
 */
export function beamSolve(start: Board, rule: RuleName, width: number): number[] {
  if (isEmptyCells(start.cells)) return [];
  let layer: BeamNode[] = [{ board: start, parent: null, tap: -1 }];
  for (;;) {
    const seen = new Set<string>();
    const scored: { node: BeamNode; score: number; order: number }[] = [];
    for (const node of layer) {
      for (const g of findGroups(node.board).groups) {
        const child = liftGroup(node.board, g, rule);
        if (isEmptyCells(child.cells)) return pathOf(node, g[0]);
        const key = cellsKey(child.cells);
        if (seen.has(key)) continue;
        seen.add(key);
        const cn: BeamNode = { board: child, parent: node, tap: g[0] };
        scored.push({ node: cn, score: countGroups(child), order: scored.length });
      }
    }
    scored.sort((a, z) => a.score - z.score || a.order - z.order);
    layer = scored.slice(0, width).map((s) => s.node);
  }
}

// ---------------------------------------------------------------- exact search

export interface ExactResult {
  /** True if the search finished: `taps` is then a proven-shortest solution, or null if none is shorter than the limit. */
  complete: boolean;
  /** A solution, if one was found within `maxLength`. */
  taps: number[] | null;
  /** Search nodes expanded. */
  nodes: number;
}

/**
 * Exact minimum by IDA* (plan: "exact search runs on small boards to check the beam"). Heuristic: the number of
 * distinct colors left (each lift removes at most one color, so it never overestimates). A transposition table
 * per iteration skips boards already reached at the same or a shallower depth.
 *
 * Only looks for solutions of at most `maxLength` moves (pass par - 1 to ask "is there anything shorter than par?").
 * The work is capped by a node budget, not a clock, so results don't depend on the machine.
 */
export function exactSolve(start: Board, rule: RuleName, maxLength: number, nodeBudget: number): ExactResult {
  let nodes = 0;
  if (isEmptyCells(start.cells)) return { complete: true, taps: [], nodes };
  let bound = distinctColors(start.cells);
  const path: number[] = [];
  while (bound <= maxLength) {
    const table = new Map<string, number>();
    let next = Infinity;
    let found = false;
    let outOfBudget = false;
    const dfs = (b: Board, depth: number): void => {
      if (++nodes > nodeBudget) {
        outOfBudget = true;
        return;
      }
      const { groups } = findGroups(b);
      const order = groups.slice().sort((a, z) => z.length - a.length || a[0] - z[0]);
      for (const g of order) {
        const child = liftGroup(b, g, rule);
        path.push(g[0]);
        if (isEmptyCells(child.cells)) {
          found = true;
          return;
        }
        const f = depth + 1 + distinctColors(child.cells);
        if (f > bound) {
          if (f < next) next = f;
        } else {
          const key = cellsKey(child.cells);
          const prev = table.get(key);
          if (prev === undefined || prev > depth + 1) {
            table.set(key, depth + 1);
            dfs(child, depth + 1);
            if (found || outOfBudget) return;
          }
        }
        path.pop();
      }
    };
    dfs(start, 0);
    if (found) return { complete: true, taps: path.slice(), nodes };
    if (outOfBudget) return { complete: false, taps: null, nodes };
    if (next === Infinity) break;
    bound = next;
  }
  return { complete: true, taps: null, nodes };
}

// ---------------------------------------------------------------- simulated players

/**
 * The plan's careful player: looks one move ahead and lifts the group that leaves the fewest groups.
 * Ties go to the bigger group, then to the top-left-most one.
 */
export function carefulPlay(start: Board, rule: RuleName): number[] {
  const taps: number[] = [];
  let b = start;
  while (!isEmptyCells(b.cells)) {
    let best: Board | null = null;
    let bestTap = -1;
    let bestScore = Infinity;
    for (const g of findGroups(b).groups) {
      const child = liftGroup(b, g, rule);
      const score = findGroups(child).groups.length * 1000 - g.length;
      if (score < bestScore) {
        bestScore = score;
        best = child;
        bestTap = g[0];
      }
    }
    taps.push(bestTap);
    b = best!;
  }
  return taps;
}

/** The plan's naive player: always lifts the biggest group (ties: top-left-most). */
export function naivePlay(start: Board, rule: RuleName): number[] {
  const taps: number[] = [];
  let b = start;
  while (!isEmptyCells(b.cells)) {
    let best: number[] | null = null;
    for (const g of findGroups(b).groups) if (!best || g.length > best.length) best = g;
    taps.push(best![0]);
    b = liftGroup(b, best!, rule);
  }
  return taps;
}

/**
 * A human-like, imperfect player. At each step it scores every lift by the groups left afterwards (fewer is
 * better) and picks one at random, weighted by how far it is from the best score: `weights[d]` is the weight of a
 * lift d groups worse than the best (beyond the table's end, weight 0). A lift that empties the tray always
 * scores best. Integer weights and the seeded Random keep it reproducible.
 *
 * `lookahead` 2 scores a lift by the best groups-left after one more lift, like a player who thinks two taps ahead.
 */
export interface NoisyPlayer {
  weights: readonly number[];
  lookahead: 1 | 2;
}

export function noisyPlay(start: Board, rule: RuleName, player: NoisyPlayer, rand: { int(n: number): number }): number {
  let moves = 0;
  let b = start;
  const scores: number[] = [];
  const children: Board[] = [];
  while (!isEmptyCells(b.cells)) {
    const { groups } = findGroups(b);
    scores.length = 0;
    children.length = 0;
    let best = Infinity;
    for (const g of groups) {
      const child = liftGroup(b, g, rule);
      let s: number;
      if (isEmptyCells(child.cells)) s = -1;
      else if (player.lookahead === 1) s = countGroups(child);
      else {
        s = Infinity;
        for (const g2 of findGroups(child).groups) {
          const gc = liftGroup(child, g2, rule);
          const s2 = isEmptyCells(gc.cells) ? -1 : countGroups(gc);
          if (s2 < s) s = s2;
        }
      }
      scores.push(s);
      children.push(child);
      if (s < best) best = s;
    }
    let total = 0;
    const w = player.weights;
    for (let i = 0; i < scores.length; i++) {
      const d = scores[i] - best;
      total += d < w.length ? w[d] : 0;
    }
    let pick = rand.int(total);
    let chosen = 0;
    for (let i = 0; i < scores.length; i++) {
      const d = scores[i] - best;
      const wi = d < w.length ? w[d] : 0;
      if (pick < wi) {
        chosen = i;
        break;
      }
      pick -= wi;
    }
    b = children[chosen];
    moves++;
  }
  return moves;
}

// ---------------------------------------------------------------- metrics

/** Sizes of the groups each tap of a solution lifts, in order. */
export function liftSizes(start: Board, taps: readonly number[], rule: RuleName): number[] {
  const sizes: number[] = [];
  let b = start;
  for (const tap of taps) {
    const { groupOf, groups } = findGroups(b);
    const g = groups[groupOf[tap]];
    if (!g) throw new Error(`liftSizes: tap ${tap} hits an empty cell`);
    sizes.push(g.length);
    b = liftGroup(b, g, rule);
  }
  return sizes;
}

export interface KeyMoveReport {
  /** Steps of the solution where most other choices cost 2 or more extra moves. */
  keyMoves: number;
  /** Per step: how many other choices there were, and how many of them cost 2+ extra moves. */
  steps: { choices: number; costly: number }[];
}

/**
 * The plan's "key moves" hardness signal. At each step of the solution, every other group is tried and the rest
 * of the board is solved with a small beam. A step is key if more than half of the other choices end up 2 or
 * more moves longer than the solution. A small beam can overestimate, so this is a signal, not a proof.
 */
export function keyMoves(start: Board, taps: readonly number[], rule: RuleName, probeWidth: number): KeyMoveReport {
  const steps: { choices: number; costly: number }[] = [];
  let b = start;
  for (let i = 0; i < taps.length; i++) {
    const remaining = taps.length - i;
    const { groupOf, groups } = findGroups(b);
    const chosen = groupOf[taps[i]];
    let choices = 0;
    let costly = 0;
    for (let gi = 0; gi < groups.length; gi++) {
      if (gi === chosen) continue;
      choices++;
      const child = liftGroup(b, groups[gi], rule);
      const cost = 1 + beamSolve(child, rule, probeWidth).length;
      if (cost - remaining >= 2) costly++;
    }
    steps.push({ choices, costly });
    b = liftGroup(b, groups[chosen], rule);
  }
  return { keyMoves: steps.filter((s) => s.choices > 0 && s.costly * 2 > s.choices).length, steps };
}
